<?php
namespace App\Queries\Catalog;
use App\Models\{Banner,FeaturedCollection,FeaturedProduct,Lookbook,Product};
class HomepageQuery { public function data(): array { $now=now(); $active=fn($q)=>$q->where('is_active',true)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',$now))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>=',$now)); return ['banners'=>Banner::query()->tap($active)->orderBy('sort_order')->get(),'featuredCollections'=>FeaturedCollection::query()->tap($active)->with('collection:id,name,slug,hero_image')->orderBy('sort_order')->get(),'featuredProducts'=>FeaturedProduct::query()->tap($active)->with('product.brand','product.images')->orderBy('sort_order')->get(),'lookbooks'=>Lookbook::query()->where('status','published')->where('published_at','<=',$now)->latest('published_at')->take(6)->get(),'newProducts'=>Product::query()->where('status','active')->where('is_active',true)->where('is_new',true)->with('images')->latest()->take(8)->get()]; } }
